const angleMaps = {
  "strict orthogonal grid": [0, Math.PI/2, Math.PI, 3*Math.PI/2],
  "chamfered 45 truss": [0, Math.PI/4, Math.PI/2, 3*Math.PI/4, Math.PI, 5*Math.PI/4, 3*Math.PI/2, 7*Math.PI/4],
  "diagonal bracing": [Math.PI/4, 3*Math.PI/4, 5*Math.PI/4, 7*Math.PI/4],
  "octagonal lattice": [0, Math.PI/4, Math.PI/2, 3*Math.PI/4, Math.PI, 5*Math.PI/4, 3*Math.PI/2, 7*Math.PI/4],
  "diamond chevron": [Math.PI/6, 5*Math.PI/6, 7*Math.PI/6, 11*Math.PI/6],
  "fractured crystalline": [0, Math.PI/6, Math.PI/3, Math.PI/2, 2*Math.PI/3, 5*Math.PI/6, Math.PI, 7*Math.PI/6, 4*Math.PI/3, 3*Math.PI/2, 5*Math.PI/3, 11*Math.PI/6]
};

const swarmMaps = {
  "calm drift": { spd: 1.2, impl: 0.001 },
  "roving magnetic cluster": { spd: 1.5, impl: 0.005 },
  "twin vortex orbital": { spd: 2.5, impl: 0.01 },
  "jittery pulse core": { spd: 5.0, impl: 0.02 },
  "periodic implosion surge": { spd: 4.0, impl: 0.08 },
  "violent collapse frenzy": { spd: 8.0, impl: 0.2 }
};

const gaugeMaps = {
  "wire filament": 6,
  "slender conduit": 9,
  "industrial rebar": 12,
  "heavy girder": 16,
  "reinforced bulkhead": 20,
  "monolithic strut": 26
};

const decayMaps = {
  "eternal steel": 0.00025,
  "slow oxidation": 0.0015,
  "flaky patina": 0.004,
  "brittle spalling": 0.0075,
  "aggressive rust molt": 0.015,
  "rapid ash crumble": 0.03
};

const colorMaps = {
  "sterile raw iron": [[180,190,200], [80,85,90]],
  "forged graphite amber": [[60,60,60], [200,120,40]],
  "copper slag verdigris": [[180,100,60], [60,180,140]],
  "sulfuric cadmium rust": [[220,180,50], [180,60,20]],
  "toxic oxide violet": [[100,150,140], [120,40,160]],
  "incandescent kiln slag": [[255,220,100], [40,20,20]]
};

const MAX_NODES = 2500;
const MAX_ATTRACTORS = 350;
const SEG_LEN = 15;
const MAX_DIST = 200;
const MIN_DIST = 8;
const CELL_SIZE = 80;
const BATCH_BINS = 10;
const SAFETY_FLOOR = 800;
const SOFT_CAP = 2000;

let nodes = [];
let attractors = [];
let grid = new Map();
let implosionState = 0; 
let cx, cy;
let centerRoots = [];

function spawnCenter(p) {
  let r1 = {sx: cx, sy: cy, ex: cx, ey: cy-20, age: 0, ticks: 0, root: true, active: true};
  let r2 = {sx: cx, sy: cy, ex: cx, ey: cy+20, age: 0, ticks: 0, root: true, active: true};
  let r3 = {sx: cx, sy: cy, ex: cx-20, ey: cy, age: 0, ticks: 0, root: true, active: true};
  let r4 = {sx: cx, sy: cy, ex: cx+20, ey: cy, age: 0, ticks: 0, root: true, active: true};
  centerRoots = [r1, r2, r3, r4];
  nodes.push(r1, r2, r3, r4);
}

p.setup = function() {
  p.createCanvas(800, 800);
  cx = p.width / 2;
  cy = p.height / 2;

  for(let i = 20; i < p.width; i += 40) {
    nodes.push({sx: i, sy: 0, ex: i, ey: 20, age: 0, ticks: 0, root: true, active: true});
    nodes.push({sx: i, sy: p.height, ex: i, ey: p.height-20, age: 0, ticks: 0, root: true, active: true});
    nodes.push({sx: 0, sy: i, ex: 20, ey: i, age: 0, ticks: 0, root: true, active: true});
    nodes.push({sx: p.width, sy: i, ex: p.width-20, ey: i, age: 0, ticks: 0, root: true, active: true});
  }

  spawnCenter(p);
};

function snapAngle(angle, mode) {
  let angles = angleMaps[mode] || angleMaps["strict orthogonal grid"];
  let best = angles[0];
  let minDiff = 999;
  for (let a of angles) {
    let diff = Math.abs(Math.atan2(Math.sin(angle - a), Math.cos(angle - a)));
    if (diff < minDiff) {
      minDiff = diff;
      best = a;
    }
  }
  return best;
}

p.draw = function() {
  const orthodoxy = p.getSynthVar('branching_orthodoxy') || 'strict orthogonal grid';
  const swarm = p.getSynthVar('attractor_swarm') || 'calm drift';
  const gauge = p.getSynthVar('beam_gauge') || 'wire filament';
  const decayRate = p.getSynthVar('decay_erosion') || 'eternal steel';
  const alloy = p.getSynthVar('corrosion_alloy') || 'sterile raw iron';

  const swarmConf = swarmMaps[swarm];
  const decayInc = decayMaps[decayRate];
  const weight = gaugeMaps[gauge];
  const colors = colorMaps[alloy];

  p.background(10, 12, 15, 200);

  let centerAlive = false;
  for (let r of centerRoots) {
    if (r.active && !r.dead) {
      centerAlive = true;
      break;
    }
  }
  if (!centerAlive) {
    spawnCenter(p);
  }

  if (p.random() < 0.3) {
    attractors.push({x: p.random(0, p.width), y: p.random(0, 40), vx: 0, vy: 0});
    attractors.push({x: p.random(0, p.width), y: p.random(p.height-40, p.height), vx: 0, vy: 0});
    attractors.push({x: p.random(0, 40), y: p.random(0, p.height), vx: 0, vy: 0});
    attractors.push({x: p.random(p.width-40, p.width), y: p.random(0, p.height), vx: 0, vy: 0});
  }

  while(attractors.length < MAX_ATTRACTORS) {
    attractors.push({
      x: p.random(80, p.width-80),
      y: p.random(80, p.height-80),
      vx: p.random(-1, 1),
      vy: p.random(-1, 1)
    });
  }

  if (p.random() < swarmConf.impl && implosionState === 0) {
    implosionState = 60;
  }

  for (let a of attractors) {
    if (implosionState > 0) {
      let dx = cx - a.x;
      let dy = cy - a.y;
      let mag = Math.max(1, Math.sqrt(dx*dx + dy*dy));
      a.x += (dx / mag) * swarmConf.spd * 3;
      a.y += (dy / mag) * swarmConf.spd * 3;
    } else {
      a.x += a.vx * swarmConf.spd + (p.noise(a.x*0.01, p.frameCount*0.01)-0.5);
      a.y += a.vy * swarmConf.spd + (p.noise(a.y*0.01, p.frameCount*0.01)-0.5);
      if (a.x < 0 || a.x > p.width) a.vx *= -1;
      if (a.y < 0 || a.y > p.height) a.vy *= -1;
    }
  }
  if (implosionState > 0) implosionState--;

  grid.clear();
  for (let n of nodes) {
    if (!n.active) continue;
    let key = Math.floor(n.ex / CELL_SIZE) + ',' + Math.floor(n.ey / CELL_SIZE);
    if (!grid.has(key)) grid.set(key, []);
    grid.get(key).push(n);
    n.pulls = 0;
    n.dx = 0;
    n.dy = 0;
  }

  let nextAttractors = [];
  for (let a of attractors) {
    let ax = Math.floor(a.x / CELL_SIZE);
    let ay = Math.floor(a.y / CELL_SIZE);
    let closestNode = null;
    let record = MAX_DIST;

    for (let ox = -1; ox <= 1; ox++) {
      for (let oy = -1; oy <= 1; oy++) {
        let key = (ax + ox) + ',' + (ay + oy);
        let cell = grid.get(key);
        if (!cell) continue;
        for (let n of cell) {
          let d = p.dist(a.x, a.y, n.ex, n.ey);
          if (d < MIN_DIST) {
            record = -1;
            break;
          } else if (d < record) {
            record = d;
            closestNode = n;
          }
        }
        if (record < 0) break;
      }
      if (record < 0) break;
    }

    if (record > 0) {
      nextAttractors.push(a);
      if (closestNode) {
        let dir = Math.atan2(a.y - closestNode.ey, a.x - closestNode.ex);
        closestNode.dx += Math.cos(dir);
        closestNode.dy += Math.sin(dir);
        closestNode.pulls++;
      }
    }
  }
  attractors = nextAttractors;

  let activeDecay = nodes.length > SAFETY_FLOOR ? decayInc : 0;
  if (nodes.length > SOFT_CAP) {
    activeDecay += 0.005;
  }
  if (implosionState > 0 && nodes.length > SAFETY_FLOOR) {
    activeDecay += 0.01;
  }

  let newNodes = [];
  for (let n of nodes) {
    if (n.active && n.pulls > 0) {
      let avgDir = Math.atan2(n.dy, n.dx);
      let snapped = snapAngle(avgDir, orthodoxy);
      let nx = n.ex + Math.cos(snapped) * SEG_LEN;
      let ny = n.ey + Math.sin(snapped) * SEG_LEN;

      if (nx > 0 && nx < p.width && ny > 0 && ny < p.height) {
        newNodes.push({sx: n.ex, sy: n.ey, ex: nx, ey: ny, age: 0, ticks: 0, root: false, active: true});
      } else {
        n.active = false;
      }
    }

    if (!n.root) {
      n.ticks++;
      if (n.ticks > 15) {
        n.age += activeDecay;
        if (n.age >= 1.0) n.dead = true;
      }
    }
  }

  nodes = nodes.filter(n => n.root || !n.dead);
  for (let nn of newNodes) nodes.push(nn);

  if (nodes.length > MAX_NODES) {
    let killCount = nodes.length - MAX_NODES;
    for (let n of nodes) {
      if (!n.root && killCount > 0) {
        n.age += 0.5;
        killCount--;
      }
    }
  }

  let bins = Array.from({length: BATCH_BINS}, () => []);
  for (let n of nodes) {
    let binIdx = Math.min(BATCH_BINS - 1, Math.floor(n.age * BATCH_BINS));
    bins[binIdx].push(n);
  }

  p.drawingContext.lineCap = 'square';
  p.drawingContext.lineJoin = 'miter';

  for (let i = 0; i < BATCH_BINS; i++) {
    if (bins[i].length === 0) continue;

    let t = i / (BATCH_BINS - 1);
    let r = p.lerp(colors[0][0], colors[1][0], t);
    let g = p.lerp(colors[0][1], colors[1][1], t);
    let b = p.lerp(colors[0][2], colors[1][2], t);
    let alpha = p.lerp(255, 140, Math.pow(t, 2));

    p.stroke(r, g, b, alpha);
    p.strokeWeight(Math.max(3.5, weight * p.lerp(1.0, 0.4, t)));

    p.drawingContext.beginPath();
    for (let n of bins[i]) {
      p.drawingContext.moveTo(n.sx, n.sy);
      p.drawingContext.lineTo(n.ex, n.ey);
    }
    p.drawingContext.stroke();
  }
};
